mapper.update:
UPDATE imp_delivery_evidence
SET acc_next_retry_at = #{query.nextRetryAt},
    version = version + 1,
    updater = '0',
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.evidenceId}
  AND current_revision_no = #{query.currentRevision}
  AND acc_sync_status = 'PUBLISHED_PENDING_ACC'
  AND acc_last_event_id = #{query.eventId}
  AND acc_retry_count = 0
  AND acc_next_retry_at IS NULL
  AND version = #{query.expectedVersion}
  AND deleted = b'0'

UPDATE imp_delivery_evidence
SET acc_sync_status = #{query.targetStatus},
    version = version + 1,
    updater = '0',
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.evidenceId}
  AND current_revision_no = #{query.currentRevision}
  AND acc_sync_status = #{query.expectedStatus}
  AND version = #{query.expectedVersion}
  AND deleted = b'0'

UPDATE imp_delivery_evidence
SET acc_sync_status = #{query.targetStatus},
    acc_retry_count = #{query.newRetryCount},
    acc_next_retry_at = #{query.nextRetryAt},

        acc_last_event_id = #{query.eventId},
        acc_last_published_at = #{query.publishedAt},

    version = version + 1,
    updater = '0',
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.evidenceId}
  AND current_revision_no = #{query.currentRevision}
  AND acc_sync_status = #{query.expectedStatus}
  AND acc_retry_count = #{query.expectedRetryCount}
  AND version = #{query.expectedVersion}
  AND deleted = b'0'
